fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    str1.iter()
        .map(|&c| {
            if ('a'..='z').contains(&c) {
                // ASCII lowercase -> uppercase
                ((c as u8) - b'a' + b'A') as char
            } else if ('A'..='Z').contains(&c) {
                // ASCII uppercase -> lowercase
                ((c as u8) - b'A' + b'a') as char
            } else {
                // Non-ASCII letters, digits, punctuation, whitespace, etc. unchanged
                c
            }
        })
        .collect()
}

